// intake_decision / intake_condition / conditional_start row-level security and integrity — generated by
// `pnpm gen:migration` (02-architecture §4, 04-testing §3); SOP-DEL-01 §8, §9 cases added (E2 AC2–AC4).
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  conditionalStart,
  createDatabase,
  eq,
  handoverCard,
  inActorTransaction,
  intakeCondition,
  intakeDecision,
  migrateUp,
  site,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const siteA = randomUUID();
const cardA1 = randomUUID();
const cardA2 = randomUUID();
const decisionA1 = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const submitted = { status: 'submitted' as const, submittedAt: new Date(), submittedBy: staff.id };
const decisionOf = (cardId: string, more: Partial<typeof intakeDecision.$inferInsert> = {}) => ({
  id: randomUUID(),
  clientId: clientA,
  cardId,
  decision: 'accepted_with_conditions' as const,
  folderStandard: 'S' as const,
  decidedBy: staff.id,
  ...more,
});
const conditionOf = (itemCode: string, more: Partial<typeof intakeCondition.$inferInsert> = {}) => ({
  id: randomUUID(),
  clientId: clientA,
  decisionId: decisionA1,
  itemCode,
  text: 'Scanned copy of the confirmed design',
  deadline: '2026-11-09',
  ...more,
});
const startOf = (more: Partial<typeof conditionalStart.$inferInsert> = {}) => ({
  id: randomUUID(),
  clientId: clientA,
  cardId: cardA2,
  authorisedBy: staff.id,
  missingItems: ['C2'],
  deadline: '2026-11-09',
  writtenRef: 'DingTalk message 0001',
  ...more,
});
let testDb: TestDatabase;
let database: Database;

type Tx = Parameters<Parameters<typeof inActorTransaction>[2]>[0];
const asStaff = <T>(work: (tx: Tx) => Promise<T>) => inActorTransaction(database.db, staff, work);
const countsFor = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) => [
    (await tx.select().from(intakeDecision)).length,
    (await tx.select().from(intakeCondition)).length,
    (await tx.select().from(conditionalStart)).length,
  ]);

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await asStaff(async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx.insert(site).values({
      id: siteA,
      clientId: clientA,
      projectId: 'CLIENTA-ES-MAD-001',
      countryCode: 'ES',
      cityCode: 'MAD',
      cityName: 'Madrid',
      runningNo: 1,
      name: 'Site 001',
      standard: 'S',
    });
    await tx.insert(handoverCard).values([
      { id: cardA1, clientId: clientA, siteId: siteA, version: 1, package: 'full', ...submitted },
      {
        id: cardA2,
        clientId: clientA,
        siteId: siteA,
        version: 2,
        package: 'full',
        status: 'returned',
        submittedAt: new Date(),
        submittedBy: staff.id,
      },
    ]);
    await tx.insert(intakeDecision).values(decisionOf(cardA1, { id: decisionA1 }));
    await tx.insert(intakeCondition).values(conditionOf('B2'));
    await tx.insert(conditionalStart).values(startOf());
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see decisions, conditions and conditional starts', async () => {
  expect(await countsFor(staff)).toEqual([1, 1, 1]);
});

it('clients and partners see none of it and cannot write', async () => {
  expect(await countsFor(userOfA)).toEqual([0, 0, 0]);
  expect(await countsFor(partnerOfA)).toEqual([0, 0, 0]);
  await expect(
    inActorTransaction(database.db, userOfA, (tx) => tx.insert(intakeDecision).values(decisionOf(cardA2))),
  ).rejects.toThrow();
});

it('one decision per card version (§8: a Returned card comes back as the next version)', async () => {
  await expect(asStaff((tx) => tx.insert(intakeDecision).values(decisionOf(cardA1)))).rejects.toThrow();
});

it('Returned lists the gaps and assigns no PM (§8)', async () => {
  await expect(
    asStaff((tx) => tx.insert(intakeDecision).values(decisionOf(cardA2, { decision: 'returned' }))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) =>
      tx
        .insert(intakeDecision)
        .values(decisionOf(cardA2, { decision: 'returned', reasons: 'A1 missing', assignedPmId: staff.id })),
    ),
  ).rejects.toThrow();
  await asStaff((tx) =>
    tx.insert(intakeDecision).values(decisionOf(cardA2, { decision: 'returned', reasons: 'A1 missing' })),
  );
});

it("every row's client is its card's client", async () => {
  await expect(
    asStaff((tx) => tx.insert(intakeCondition).values(conditionOf('B3', { clientId: clientB }))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(conditionalStart).values(startOf({ clientId: clientB }))),
  ).rejects.toThrow();
});

it('a condition is listed once per item, has text, and is met with a date', async () => {
  await expect(asStaff((tx) => tx.insert(intakeCondition).values(conditionOf('B2')))).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(intakeCondition).values(conditionOf('B4', { text: ' ' }))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) =>
      tx.update(intakeCondition).set({ status: 'met' }).where(eq(intakeCondition.itemCode, 'B2')),
    ),
  ).rejects.toThrow();
});

it('a Conditional Start names the missing items and the written authorisation (§9)', async () => {
  await expect(
    asStaff((tx) => tx.insert(conditionalStart).values(startOf({ missingItems: [] }))),
  ).rejects.toThrow();
  await expect(
    asStaff((tx) => tx.insert(conditionalStart).values(startOf({ writtenRef: '' }))),
  ).rejects.toThrow();
});
